import math

def is_square(k):
    if k < 1:
        return False
    root = int(math.isqrt(k))
    return root * root == k

def check_cool(n):
    """
    Checks if an integer n is a cool integer using backtracking.
    """

    def backtrack(current_sum, used_numbers, length):
        """
        current_sum: the sum of the prefix built so far.
        used_numbers: a set of numbers already used in the permutation.
        length: the current length of the permutation built.
        """
        if length == n:
            # Successfully built a permutation of length n
            return True

        # Try appending every unused number k
        for k in range(1, n + 1):
            if k not in used_numbers:
                new_sum = current_sum + k

                # Pruning condition: The prefix sum must not be a perfect square
                if not is_square(new_sum):
                    used_numbers.add(k)
                    if backtrack(new_sum, used_numbers, length + 1):
                        return True
                    # Backtrack step: remove k
                    used_numbers.remove(k)

        return False

    # Start the search
    return backtrack(0, set(), 0)

# Search for cool integers up to n=15
cool_integers = []
for n in range(1, 16):
    if check_cool(n):
        cool_integers.append(n)

print(f"Cool integers up to 15: {cool_integers}")

def is_square(n):
    if n < 0:
        return False
    if n == 0:
        return True
    root = int(n**0.5)
    return root * root == n

def check_cool_constraint(n):
    S_n = n * (n + 1) // 2
    return is_square(S_n)

sequence = [1, 8, 49, 288, 1681, 9800]

results = {}
for i, n in enumerate(sequence):
    is_nc = check_cool_constraint(n)
    results[n] = is_nc
    print(f"n={n} (Rank {i+1}): S_n = {n*(n+1)//2}. Is S_n a perfect square? {is_nc}")

# Specific confirmation required by the task
print(f"\nVerification of 5th term (n=1681): {results[1681]}")
print(f"Verification of 6th term (n=9800): {results[9800]}")
